1	import { Injectable, NotFoundException, BadRequestException, ForbiddenException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { GeocodingService } from '../motoboy/geocoding.service';
4	import { ComissaoService } from '../motoboy/comissao.service';
5	import { SalaoService } from '../salao/salao.service';
6	import { EstoqueService } from '../estoque/estoque.service';
7	import { CombosService, ItemExpandido } from '../combos/combos.service';
8	
9	const STATUS_VALIDOS = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery', 'delivered', 'canceled'] as const;
10	type Status = typeof STATUS_VALIDOS[number];
11	
12	@Injectable()
13	export class PedidosService {
14	  constructor(
15	    private supabase: SupabaseService,
16	    private geocoding: GeocodingService,
17	    private comissao: ComissaoService,
18	    private salaoService: SalaoService,
19	    private estoque: EstoqueService,
20	    private combos: CombosService,
21	  ) {}
22	
23	  // Roteia os itens do pedido delivery pro mesmo mecanismo de KDS por setor que o
24	  // módulo Salão já usa: copia impressora_id do produto pro item, marca status
25	  // "enviado" (aparece em Produção/Bar/Cozinha filtrado por setor) e gera job de
26	  // impressão por setor pras impressoras com agente local pareado. Idempotente —
27	  // só processa item que ainda não foi enviado (enviado_em null), então pode chamar
28	  // de novo sem duplicar (ex: pedido volta de "confirmed" -> "pending" -> "confirmed").
29	  private async rotearItensParaSetor(pedidoId: number, restauranteId: number) {
30	    const { data: pendentes, error } = await this.supabase.client
31	      .from('order_items')
32	      .select('id, quantity, products(name, description, impressora_id, impressoras(id, nome, setor, nome_sistema))')
33	      .eq('order_id', pedidoId)
34	      .is('enviado_em', null);
35	    if (error) throw error;
36	    if (!pendentes?.length) return;
37	
38	    const agora = new Date().toISOString();
39	    await this.supabase.client
40	      .from('order_items')
41	      .update({ status: 'enviado', enviado_em: agora })
42	      .in('id', pendentes.map((p: any) => p.id));
43	
44	    for (const item of pendentes as any[]) {
45	      const impressoraId = item.products?.impressora_id ?? null;
46	      if (impressoraId) {
47	        await this.supabase.client.from('order_items').update({ impressora_id: impressoraId }).eq('id', item.id);
48	      }
49	    }
50	
51	    const grupos = new Map<string, { setor: string; impressora_id: number; nome_sistema: string | null; itens: any[] }>();
52	    for (const item of pendentes as any[]) {
53	      const impressora = item.products?.impressoras;
54	      if (!impressora?.id) continue; // produto sem impressora configurada — não gera job
55	      const chave = String(impressora.id);
56	      if (!grupos.has(chave)) {
57	        grupos.set(chave, { setor: impressora.setor, impressora_id: impressora.id, nome_sistema: impressora.nome_sistema ?? null, itens: [] });
58	      }
59	      grupos.get(chave)!.itens.push({
60	        product_name: item.products?.name,
61	        description: item.products?.description,
62	        quantity: item.quantity,
63	      });
64	    }
65	
66	    const comandaLike = { cliente_mesa_nome: `Pedido delivery #${pedidoId}` };
67	    for (const grupo of grupos.values()) {
68	      if (!grupo.nome_sistema) continue; // sem agente local pareado — sem job, staff reimprime pela tela do setor
69	      const conteudo = this.salaoService.formatarTicketTexto(grupo.setor, comandaLike, grupo.itens);
70	      const { error: errJob } = await this.supabase.client.from('impressao_jobs').insert({
71	        restaurant_id: restauranteId,
72	        impressora_id: grupo.impressora_id,
73	        conteudo,
74	      });
75	      if (errJob) throw errJob;
76	    }
77	  }
78	
79	  private async geocodificarEnderecoCliente(customerId: number) {
80	    const { data: customer } = await this.supabase.client
81	      .from('customers')
82	      .select('address_json, address_geocode_hash')
83	      .eq('id', customerId)
84	      .maybeSingle();
85	    if (!customer) return;
86	
87	    const resultado = await this.geocoding.geocodificarSeNecessario(customer.address_json, customer.address_geocode_hash);
88	    if (!resultado) return;
89	
90	    await this.supabase.client
91	      .from('customers')
92	      .update({
93	        lat: resultado.lat,
94	        lng: resultado.lng,
95	        address_geocode_hash: resultado.hash,
96	        address_geocoded_at: new Date().toISOString(),
97	      })
98	      .eq('id', customerId);
99	  }
100	
101	  async listar(filtros: {
102	    empresa_id?: number;
103	    status?: string;
104	    user_id?: string;
105	    data_inicio?: string;
106	    data_fim?: string;
107	    limite?: number;
108	  }) {
109	    let query = this.supabase.client
110	      .from('orders')
111	      .select('id, total, frete_cobrado, status, payment_method, restaurant_id, customer_id, user_id, created_at, pago_em, canal')
112	      .order('created_at', { ascending: false })
113	      .limit(filtros.limite ?? 50);
114	
115	    if (filtros.empresa_id) query = query.eq('restaurant_id', filtros.empresa_id);
116	    if (filtros.status) query = query.eq('status', filtros.status);
117	    if (filtros.user_id) query = query.eq('user_id', filtros.user_id);
118	    if (filtros.data_inicio) query = query.gte('created_at', filtros.data_inicio);
119	    if (filtros.data_fim) query = query.lte('created_at', filtros.data_fim + 'T23:59:59');
120	
121	    const { data, error } = await query;
122	    if (error) throw error;
123	    return { pedidos: data, total: data?.length ?? 0 };
124	  }
125	
126	  // Uso público (controller) — exige provar posse do pedido (admin ou dono).
127	  async buscar(id: number, callerUserId: string, callerRole: string) {
128	    const resultado = await this.buscarBruto(id);
129	    if (callerRole !== 'admin' && resultado.pedido.user_id !== callerUserId) {
130	      throw new ForbiddenException('Você não tem acesso a este pedido');
131	    }
132	    return resultado;
133	  }
134	
135	  // Uso interno — quem chama já validou a posse por outro caminho (ex.:
136	  // RestauranteService.buscarPedidoDoRestaurante() confere restaurant_id logo
137	  // em seguida). Nunca expor direto num controller sem checagem de posse.
138	  async buscarBruto(id: number) {
139	    const { data: pedido, error } = await this.supabase.client
140	      .from('orders')
141	      .select('id, total, troco_para, frete_cobrado, entrega_pagamento, status, payment_method, canal, pago_em, comprovante_pagamento_url, restaurant_id, customer_id, user_id, motoboy_id, motoboy_lat, motoboy_lng, motoboy_location_at, delivery_notes, delivery_occurrence, cancel_reason, created_at, updated_at')
142	      .eq('id', id)
143	      .maybeSingle();
144	
145	    if (error) throw error;
146	    if (!pedido) throw new NotFoundException(`Pedido ${id} não encontrado`);
147	
148	    const [{ data: itensRaw }, { data: cliente }, { data: empresa }, { data: motoboy }, { data: pagamento }] = await Promise.all([
149	      this.supabase.client
150	        .from('order_items')
151	        .select('id, quantity, unit_price, product_id, combo_nome, combo_quantidade, status, enviado_em, preparando_em')
152	        .eq('order_id', id),
153	      pedido.customer_id
154	        ? this.supabase.client.from('customers').select('id, name, email, phone_e164, address_json').eq('id', pedido.customer_id).maybeSingle()
155	        : Promise.resolve({ data: null }),
156	      this.supabase.client
157	        .from('restaurants')
158	        .select('id, name, comissao_pct, address')
159	        .eq('id', pedido.restaurant_id)
160	        .maybeSingle(),
161	      pedido.motoboy_id
162	        ? this.supabase.client.from('motoboys').select('id, name, phone').eq('id', pedido.motoboy_id).maybeSingle()
163	        : Promise.resolve({ data: null }),
164	      this.supabase.client.from('pagamentos').select('id, valor, tipo, status').eq('order_id', id).eq('status', 'paid').maybeSingle(),
165	    ]);
166	
167	    // Enrich items with product names
168	    let itens = itensRaw ?? [];
169	    if (itens.length > 0) {
170	      const prodIds = itens.map((i: any) => i.product_id);
171	      const { data: prods } = await this.supabase.client.from('products').select('id, name').in('id', prodIds);
172	      const prodMap = Object.fromEntries((prods ?? []).map((p: any) => [p.id, p.name]));
173	      itens = itens.map((i: any) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
174	    }
175	
176	    return { pedido, itens, cliente, empresa, motoboy, pagamento_pago: pagamento ?? null };
177	  }
178	
179	  async criar(body: {
180	    restaurant_id: number;
181	    customer_id?: number;
182	    payment_method: string;
183	    troco_para?: number;
184	    user_id: string;
185	    itens: { product_id?: number; combo_id?: number; quantity: number }[];
186	  }) {
187	    if (!body.itens?.length) throw new BadRequestException('Pedido precisa de pelo menos 1 item');
188	
189	    const itensDiretos = body.itens.filter((i) => i.product_id != null);
190	    const itensCombo = body.itens.filter((i) => i.combo_id != null);
191	
192	    // Busca preços dos produtos vendidos diretamente (fora de combo)
193	    const prodIds = itensDiretos.map((i) => i.product_id as number);
194	    const { data: produtos, error: errProd } = await this.supabase.client
195	      .from('products')
196	      .select('id, price, is_active')
197	      .in('id', prodIds.length ? prodIds : [0]);
198	
199	    if (errProd) throw errProd;
200	
201	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
202	
203	    for (const item of itensDiretos) {
204	      const prod = prodMap[item.product_id as number];
205	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
206	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
207	    }
208	
209	    // Combo não é vendável direto — vira as linhas dos produtos reais que o compõem,
210	    // com preço escalado pra bater o valor promocional do combo (ver CombosService).
211	    const linhasCombo: ItemExpandido[] = (
212	      await Promise.all(itensCombo.map((i) => this.combos.expandir(i.combo_id as number, i.quantity, body.restaurant_id)))
213	    ).flat();
214	
215	    const linhasDiretas: ItemExpandido[] = itensDiretos.map((item) => ({
216	      product_id: item.product_id as number,
217	      quantity: item.quantity,
218	      unit_price: prodMap[item.product_id as number].price,
219	    }));
220	
221	    const linhasFinais = [...linhasDiretas, ...linhasCombo];
222	
223	    const subtotal = linhasFinais.reduce((acc, l) => acc + l.unit_price * l.quantity, 0);
224	
225	    // Busca frete do restaurante e soma ao total
226	    const { data: rest } = await this.supabase.client
227	      .from('restaurants')
228	      .select('frete_motoboy, motoboy_comissao_tipo')
229	      .eq('id', body.restaurant_id)
230	      .maybeSingle();
231	
232	    const frete = parseFloat(rest?.frete_motoboy ?? 0);
233	    const total = subtotal + frete;
234	
235	    // Resolve customer_id — busca existente ou cria novo ao primeiro pedido
236	    let customerId = body.customer_id ?? null;
237	    if (!customerId && body.user_id) {
238	      const { data: c } = await this.supabase.client
239	        .from('customers')
240	        .select('id')
241	        .eq('user_id', body.user_id)
242	        .maybeSingle();
243	
244	      if (c) {
245	        customerId = c.id;
246	      } else {
247	        // Cria registro de cliente usando dados do user_profile
248	        const { data: profile } = await this.supabase.client
249	          .from('user_profiles')
250	          .select('name, email')
251	          .eq('id', body.user_id)
252	          .maybeSingle();
253	
254	        const { data: novoCliente } = await this.supabase.client
255	          .from('customers')
256	          .insert({
257	            user_id: body.user_id,
258	            name: profile?.name ?? 'Cliente',
259	            email: profile?.email ?? null,
260	          })
261	          .select('id')
262	          .single();
263	
264	        if (novoCliente) customerId = novoCliente.id;
265	      }
266	    }
267	
268	    // Geocodifica o endereço do cliente em background (best-effort) — só quando a comissão
269	    // do motoboy for por km, pra não gastar chamadas do Nominatim à toa. Nunca trava o checkout.
270	    if (customerId && rest?.motoboy_comissao_tipo === 'km') {
271	      this.geocodificarEnderecoCliente(customerId).catch(() => {});
272	    }
273	
274	    // Busca caixa aberto para vincular o pedido
275	    const { data: caixaAberto } = await this.supabase.client
276	      .from('caixas')
277	      .select('id')
278	      .eq('restaurant_id', body.restaurant_id)
279	      .eq('status', 'aberto')
280	      .maybeSingle();
281	
282	    // Cria pedido
283	    const { data: pedido, error: errPedido } = await this.supabase.client
284	      .from('orders')
285	      .insert({
286	        restaurant_id: body.restaurant_id,
287	        customer_id: customerId,
288	        payment_method: body.payment_method,
289	        troco_para: body.payment_method === 'cash' && body.troco_para ? body.troco_para : null,
290	        user_id: body.user_id,
291	        total: parseFloat(total.toFixed(2)),
292	        frete_cobrado: parseFloat(frete.toFixed(2)),
293	        status: 'pending',
294	        caixa_id: caixaAberto?.id ?? null,
295	      })
296	      .select()
297	      .single();
298	
299	    if (errPedido) throw errPedido;
300	
301	    // Cria itens — combo já chega explodido nas linhas dos produtos reais (linhasFinais)
302	    const itensPrepared = linhasFinais.map((l) => ({
303	      order_id: pedido.id,
304	      product_id: l.product_id,
305	      quantity: l.quantity,
306	      unit_price: l.unit_price,
307	      combo_nome: l.combo_nome ?? null,
308	      combo_quantidade: l.combo_quantidade ?? null,
309	    }));
310	
311	    const { error: errItens } = await this.supabase.client
312	      .from('order_items')
313	      .insert(itensPrepared);
314	
315	    if (errItens) throw errItens;
316	
317	    // Reserva o estoque assim que o pedido é criado — evita vender 2x o último item
318	    // enquanto ele ainda está pendente de confirmação. Já é por produto real, então
319	    // cobre item vendido direto e item vindo de combo igual.
320	    await this.estoque.decrementarItens(linhasFinais);
321	
322	    return { pedido, itens: itensPrepared };
323	  }
324	
325	  async atualizarStatus(id: number, status: Status) {
326	    if (!STATUS_VALIDOS.includes(status)) {
327	      throw new BadRequestException(`Status inválido: ${status}`);
328	    }
329	
330	    const { data: antes } = await this.supabase.client.from('orders').select('status').eq('id', id).maybeSingle();
331	    const statusAnterior = antes?.status;
332	
333	    const { data, error } = await this.supabase.client
334	      .from('orders')
335	      .update({ status, updated_at: new Date().toISOString() })
336	      .eq('id', id)
337	      .select('id, status, total, restaurant_id, payment_method, updated_at, motoboy_id, frete_cobrado, customer_id')
338	      .single();
339	
340	    if (error) throw error;
341	    if (!data) throw new NotFoundException(`Pedido ${id} não encontrado`);
342	
343	    if (status === 'confirmed') {
344	      await this.rotearItensParaSetor(id, data.restaurant_id);
345	    }
346	
347	    if (status === 'canceled' && statusAnterior !== 'canceled') {
348	      await this.estoque.restaurarItensDoPedido(id);
349	    }
350	
351	    // Delivery pago em dinheiro precisa creditar o caixa físico igual já acontece na
352	    // venda do salão (ver SalaoService.registrarEntradaCaixa) — sem isso "Espécie no
353	    // caixa" nunca soma a venda em dinheiro, só o fundo inicial.
354	    if (status === 'delivered' && statusAnterior !== 'delivered' && data.payment_method === 'cash') {
355	      await this.salaoService.registrarEntradaCaixa(data.restaurant_id, `Venda delivery em dinheiro - Pedido #${id}`, data.total, 'venda_dinheiro');
356	    }
357	
358	    // Comissão do motoboy: só era registrada quando o próprio motoboy confirmava a
359	    // entrega pelo app (MotoboyService.confirmarEntrega) — pedido marcado como entregue
360	    // por aqui (dono/admin, ex. quando o motoboy não usa o app) tinha motoboy_id mas
361	    // nunca gerava a linha em motoboy_comissoes, ficando invisível no relatório de
362	    // conferência. Idempotente via UNIQUE(pedido_id) em registrarComissaoEntrega.
363	    if (status === 'delivered' && statusAnterior !== 'delivered' && data.motoboy_id) {
364	      await this.comissao.registrarComissaoEntrega(data as any, data.motoboy_id);
365	    }
366	
367	    return data;
368	  }
369	
370	  async cancelar(id: number) {
371	    return this.atualizarStatus(id, 'canceled');
372	  }
373	
374	  async cancelarCliente(id: number, userId: string, motivo: string) {
375	    if (!motivo?.trim()) throw new BadRequestException('Motivo do cancelamento é obrigatório');
376	
377	    const { data: pedido, error } = await this.supabase.client
378	      .from('orders')
379	      .select('id, status, user_id, total, payment_method')
380	      .eq('id', id)
381	      .maybeSingle();
382	
383	    if (error) throw error;
384	    if (!pedido) throw new NotFoundException(`Pedido ${id} não encontrado`);
385	    if (pedido.user_id !== userId) throw new ForbiddenException('Sem permissão para cancelar este pedido');
386	    if (!['pending', 'confirmed'].includes(pedido.status)) {
387	      throw new BadRequestException('Pedido não pode ser cancelado após início do preparo');
388	    }
389	
390	    const { data: pagamento } = await this.supabase.client
391	      .from('pagamentos')
392	      .select('id, valor, tipo')
393	      .eq('order_id', id)
394	      .eq('status', 'paid')
395	      .maybeSingle();
396	
397	    const { data: atualizado, error: errUpd } = await this.supabase.client
398	      .from('orders')
399	      .update({ status: 'canceled', cancel_reason: motivo.trim(), updated_at: new Date().toISOString() })
400	      .eq('id', id)
401	      .select('id, status, cancel_reason, total, updated_at')
402	      .single();
403	
404	    if (errUpd) throw errUpd;
405	
406	    await this.estoque.restaurarItensDoPedido(id);
407	
408	    const valor_devolver = pagamento?.valor ?? 0;
409	    return {
410	      pedido: atualizado,
411	      valor_devolver,
412	      precisa_estorno: valor_devolver > 0,
413	    };
414	  }
415	
416	  // Cliente anexa o comprovante do PIX manual logo no checkout (além da foto que o
417	  // motoboy também tira na entrega — mesmo bucket/coluna, serve como segunda evidência).
418	  async uploadComprovanteCliente(id: number, userId: string, base64: string) {
419	    const { data: pedido } = await this.supabase.client
420	      .from('orders')
421	      .select('id, user_id')
422	      .eq('id', id)
423	      .maybeSingle();
424	    if (!pedido) throw new NotFoundException(`Pedido ${id} não encontrado`);
425	    if (pedido.user_id !== userId) throw new ForbiddenException('Sem permissão para este pedido');
426	
427	    const matches = base64.match(/^data:(image\/\w+);base64,(.+)$/);
428	    const mimeType = matches ? matches[1] : 'image/jpeg';
429	    const raw = matches ? matches[2] : base64;
430	    const buffer = Buffer.from(raw, 'base64');
431	    const ext = mimeType === 'image/png' ? 'png' : 'jpg';
432	    const path = `pedido-${id}-${Date.now()}.${ext}`;
433	
434	    const { error: uploadError } = await this.supabase.client.storage
435	      .from('comprovantes-pix')
436	      .upload(path, buffer, { contentType: mimeType, upsert: true });
437	    if (uploadError) throw uploadError;
438	
439	    const { data: { publicUrl } } = this.supabase.client.storage
440	      .from('comprovantes-pix')
441	      .getPublicUrl(path);
442	
443	    await this.supabase.client
444	      .from('orders')
445	      .update({ comprovante_pagamento_url: publicUrl, updated_at: new Date().toISOString() })
446	      .eq('id', id);
447	
448	    return { url: publicUrl };
449	  }
450	}
