24	  // Idempotente via UNIQUE(pedido_id) — chamado sempre que um pedido é marcado como entregue.
25	  async registrarComissaoEntrega(pedido: PedidoParaComissao, motoboyId: number) {
26	    const { data: existente } = await this.supabase.client
27	      .from('motoboy_comissoes')
28	      .select('id')
29	      .eq('pedido_id', pedido.id)
30	      .maybeSingle();
31	    if (existente) return existente;
32	
33	    const { data: restaurant } = await this.supabase.client
34	      .from('restaurants')
35	      .select(
36	        'motoboy_comissao_tipo, motoboy_comissao_valor_fixo, motoboy_comissao_percentual, motoboy_comissao_valor_km, motoboy_comissao_km_fallback, lat, lng',
37	      )
38	      .eq('id', pedido.restaurant_id)
39	      .maybeSingle();
40	    if (!restaurant) return null;
41	
42	    // O motoboy sempre recebe o frete cobrado do cliente — o tipo configurado
43	    // (fixo/percentual/km) é um ADICIONAL somado em cima disso, não substituto.
44	    const freteRepassado = Number(pedido.frete_cobrado ?? 0);
45	    let tipo = restaurant.motoboy_comissao_tipo as string;
46	    let adicional = 0;
47	    let distanciaKm: number | null = null;
48	    let valorPorKm: number | null = null;
49	    let percentual: number | null = null;
50	    let valorBase = 0;
51	
52	    if (tipo === 'fixo') {
53	      valorBase = Number(restaurant.motoboy_comissao_valor_fixo);
54	      adicional = valorBase;
55	    } else if (tipo === 'percentual') {
56	      percentual = Number(restaurant.motoboy_comissao_percentual);
57	      valorBase = freteRepassado;
58	      adicional = freteRepassado * (percentual / 100);
59	    } else if (tipo === 'km') {
60	      const distancia = await this.calcularDistanciaPedido(pedido.customer_id, restaurant.lat, restaurant.lng);
61	      if (distancia !== null) {
62	        distanciaKm = parseFloat(distancia.toFixed(2));
63	        valorPorKm = Number(restaurant.motoboy_comissao_valor_km);
64	        adicional = distancia * valorPorKm;
65	      } else {
66	        tipo = 'km_fallback';
67	        valorBase = Number(restaurant.motoboy_comissao_km_fallback);
68	        adicional = valorBase;
69	      }
70	    }
71	
72	    const comissaoValor = freteRepassado + adicional;
73	
74	    const { data, error } = await this.supabase.client
75	      .from('motoboy_comissoes')
76	      .insert({
77	        motoboy_id: motoboyId,
78	        restaurant_id: pedido.restaurant_id,
79	        pedido_id: pedido.id,
80	        tipo,
81	        valor_base: valorBase,
82	        frete_repassado: parseFloat(freteRepassado.toFixed(2)),
83	        percentual,
84	        distancia_km: distanciaKm,
85	        valor_por_km: valorPorKm,
86	        comissao_valor: parseFloat(comissaoValor.toFixed(2)),
87	      })
88	      .select()
89	      .single();
90	
91	    if (error) {
92	      // Corrida (dupla chamada) esbarra no UNIQUE(pedido_id) — não é um erro fatal aqui.
93	      this.logger.warn(`Falha ao registrar comissão do pedido ${pedido.id}: ${error.message}`);
94	      return null;
95	    }
96	    return data;
97	  }
