99	  private async calcularDistanciaPedido(
100	    customerId: number | null,
101	    restLat: number | null,
102	    restLng: number | null,
103	  ): Promise<number | null> {
104	    if (!customerId || restLat == null || restLng == null) return null;
105	
106	    const { data: customer } = await this.supabase.client
107	      .from('customers')
108	      .select('lat, lng, address_json')
109	      .eq('id', customerId)
110	      .maybeSingle();
111	    if (!customer) return null;
112	
113	    let { lat, lng } = customer;
114	    if (lat == null || lng == null) {
115	      // Best-effort: geocodifica agora caso não tenha sido feito no checkout.
116	      const enderecoTexto = this.formatarEndereco(customer.address_json);
117	      const coords = await this.geocoding.geocodeEndereco(enderecoTexto);
118	      if (!coords) return null;
119	
120	      lat = coords.lat;
121	      lng = coords.lng;
122	      const hash = crypto.createHash('md5').update(JSON.stringify(customer.address_json ?? {})).digest('hex');
123	      await this.supabase.client
124	        .from('customers')
125	        .update({ lat, lng, address_geocode_hash: hash, address_geocoded_at: new Date().toISOString() })
126	        .eq('id', customerId);
127	    }
128	
129	    return haversineKm({ lat: restLat, lng: restLng }, { lat, lng });
130	  }
131	
132	  private formatarEndereco(addressJson: any): string {
133	    if (!addressJson) return '';
134	    const { logradouro, numero, bairro, cidade, estado, cep } = addressJson;
135	    return [logradouro, numero, bairro, cidade, estado, cep].filter(Boolean).join(', ');
136	  }
137	}
