5	import { haversineKm } from '../common/geo.util';
6	import { normalizarDominio } from '../common/dominio.util';
7	import { CombosService } from '../combos/combos.service';
8	import { DEFAULT_APARENCIA_MARKETPLACE } from '../plataforma/aparencia-marketplace.constants';
9	import * as os from 'os';
10	
11	const PRODUTO_FIELDS = 'id, name, description, price, preco_promo, image_url, category_id, restaurant_id, tags, destaque, is_active, quantidade_estoque';
12	const RAIO_KM_PADRAO = 15;
13	
14	// TTL curto: aceita alguns segundos de defasagem de estoque/preço no marketplace
15	// público em troca de menos carga no Supabase (mesmo trade-off que iFood/Rappi fazem).
16	const TTL_CARDAPIO = 15;
17	const TTL_FILTROS = 60;
18	
19	@Controller('r')
20	export class CatalogoController {
21	  constructor(
22	    private supabase: SupabaseService,
23	    private supabaseJwt: SupabaseJwtService,
24	    private combosService: CombosService,
25	    private redis: RedisService,
26	  ) {}
27	
28	  // Público — branding do marketplace (logo/hero/cores) editado em /admin/aparencia.
29	  @Get('branding')
30	  async getBranding() {
31	    const { data } = await this.supabase.client
32	      .from('platform_settings')
33	      .select('config')
34	      .eq('id', 1)
35	      .maybeSingle();
36	
37	    const cfg = (data?.config ?? {}) as Record<string, any>;
38	    return { ...DEFAULT_APARENCIA_MARKETPLACE, ...(cfg.aparencia_marketplace ?? {}) };
39	  }
40	
41	  @Get('acesso')
42	  async getAcesso() {
43	    const nets = os.networkInterfaces();
44	    const todos: string[] = [];
45	    for (const iface of Object.values(nets)) {
46	      for (const net of iface ?? []) {
47	        if (net.family === 'IPv4' && !net.internal) todos.push(net.address);
48	      }
49	    }
50	    // Prioriza 192.168.x.x (WiFi doméstico/corporativo) e 10.x.x.x (redes corporativas).
51	    // Descarta 172.16-31.x.x que são WSL, Docker, Hyper-V — não acessíveis por dispositivos reais.
52	    const score = (ip: string) => {
53	      if (/^192\.168\./.test(ip)) return 0;
54	      if (/^10\./.test(ip)) return 1;
55	      if (/^172\.(1[6-9]|2\d|3[01])\./.test(ip)) return 99; // virtual — vai por último
56	      return 2;
57	    };
58	    const ips = todos.sort((a, b) => score(a) - score(b));
59	
60	    const { data } = await this.supabase.client
61	      .from('platform_settings')
62	      .select('config')
63	      .eq('id', 1)
64	      .maybeSingle();
65	    const cfg = ((data?.config ?? {}) as Record<string, any>);
66	    return {
67	      lan_ips: ips,
68	      porta: 4028,
69	      cloudflare_domain: cfg.cloudflare_domain || null,
70	    };
71	  }
72	
73	  @Get()
74	  async listarRestaurantes(
75	    @Query()
76	    query: {
77	      state?: string;
78	      city?: string;
79	      neighborhood?: string;
80	      cep?: string;
81	      lat?: string;
82	      lng?: string;
83	      raio_km?: string;
84	    },
85	    @Headers('authorization') authorization?: string,
86	  ) {
87	    // Sem Authorization o resultado é puramente função da querystring — cacheável.
88	    // Com Authorization pode depender do endereço salvo do cliente (personalizado), então
89	    // nesse caso sempre busca direto no Supabase, igual já fazia antes do cache.
90	    const cacheKey = !authorization
91	      ? `catalogo:home:${JSON.stringify(query, Object.keys(query).sort())}`
92	      : null;
93	
94	    if (cacheKey) {
95	      const cached = await this.redis.getJSON<{ restaurantes: any[] }>(cacheKey);
96	      if (cached) return cached;
97	    }
98	
99	    let q = this.supabase.client
100	      .from('restaurants')
101	      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, aparencia, frete_motoboy, lat, lng')
102	      .not('slug', 'is', null)
103	      .eq('bloqueado', false)
104	      .eq('modulo_delivery', true);
105	
106	    if (query.state) q = q.ilike('state', query.state);
107	    if (query.city) q = q.ilike('city', query.city);
108	    if (query.neighborhood) q = q.ilike('neighborhood', query.neighborhood);
109	    if (query.cep) q = q.ilike('cep', `${query.cep.replace(/\D/g, '').slice(0, 5)}%`);
110	
111	    const { data, error } = await q.order('name');
112	    if (error) throw error;
113	
114	    let restaurantes = data ?? [];
115	
116	    // Filtro/ordenação por proximidade — GPS ao vivo do navegador é a fonte principal
117	    // (comportamento esperado: cliente abre o site, mostra estabelecimentos perto de onde
118	    // ele está agora). Só cai pro endereço salvo/geocodificado do perfil (ver PerfilService)
119	    // quando o navegador não mandou lat/lng (GPS negado/indisponível) e o cliente tem token
120	    // válido — nunca confia numa coordenada de "fallback" vinda do próprio client.
121	    let lat = query.lat ? parseFloat(query.lat) : null;
122	    let lng = query.lng ? parseFloat(query.lng) : null;
123	    let usandoEnderecoSalvo = false;
124	
125	    if (lat == null && lng == null && authorization?.startsWith('Bearer ')) {
126	      const token = authorization.slice('Bearer '.length);
127	      const payload = await this.supabaseJwt.verificar(token);
128	      if (payload?.sub) {
129	        const { data: customer } = await this.supabase.client
130	          .from('customers')
131	          .select('lat, lng')
132	          .eq('user_id', payload.sub)
133	          .maybeSingle();
134	        if (customer?.lat != null && customer?.lng != null) {
135	          lat = customer.lat;
136	          lng = customer.lng;
137	          usandoEnderecoSalvo = true;
138	        }
139	      }
140	    }
141	
142	    if (lat != null && lng != null && !Number.isNaN(lat) && !Number.isNaN(lng)) {
143	      const raioKm = query.raio_km ? parseFloat(query.raio_km) : (usandoEnderecoSalvo ? RAIO_KM_PADRAO : null);
144	      restaurantes = restaurantes
145	        .map((r) => ({
146	          ...r,
147	          // 3 casas decimais (precisão de metro) — raios pequenos (20m, 50m...)
148	          // precisavam de mais que os 100m que 1 casa decimal dava.
149	          distancia_km:
150	            r.lat != null && r.lng != null
151	              ? Math.round(haversineKm({ lat, lng }, { lat: r.lat, lng: r.lng }) * 1000) / 1000
152	              : null,
153	        }))
154	        .filter((r) => raioKm == null || (r.distancia_km != null && r.distancia_km <= raioKm))
155	        .sort((a, b) => (a.distancia_km ?? Infinity) - (b.distancia_km ?? Infinity));
156	    }
157	
158	    const resultado = { restaurantes };
159	    if (cacheKey) await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
160	    return resultado;
161	  }
162	
163	  // Valores distintos de estado/cidade/bairro entre restaurantes ativos — alimenta os
164	  // dropdowns em cascata do filtro geográfico na home pública (evita carregar tudo só
165	  // pra montar as opções). Precisa vir ANTES de @Get(':slug') na ordem das rotas.
166	  @Get('filtros')
167	  async filtrosGeograficos() {
168	    const cacheKey = 'catalogo:filtros';
169	    const cached = await this.redis.getJSON<{ locais: any[] }>(cacheKey);
170	    if (cached) return cached;
171	
172	    const { data, error } = await this.supabase.client
173	      .from('restaurants')
174	      .select('state, city, neighborhood')
175	      .not('slug', 'is', null)
176	      .eq('bloqueado', false)
177	      .eq('modulo_delivery', true);
178	    if (error) throw error;
179	
180	    const vistos = new Set<string>();
181	    const locais: { state: string | null; city: string | null; neighborhood: string | null }[] = [];
182	    for (const r of data ?? []) {
183	      if (!r.state && !r.city && !r.neighborhood) continue;
184	      const key = `${r.state ?? ''}|${r.city ?? ''}|${r.neighborhood ?? ''}`;
185	      if (vistos.has(key)) continue;
186	      vistos.add(key);
187	      locais.push({ state: r.state, city: r.city, neighborhood: r.neighborhood });
188	    }
189	    const resultado = { locais };
190	    await this.redis.setJSON(cacheKey, resultado, TTL_FILTROS);
191	    return resultado;
192	  }
193	
194	  @Get('produtos')
195	  async todosOsProdutos() {
196	    const cacheKey = 'catalogo:produtos:marketplace';
197	    const cached = await this.redis.getJSON<{ produtos: any[] }>(cacheKey);
198	    if (cached) return cached;
199	
200	    const { data: restaurantes } = await this.supabase.client
201	      .from('restaurants')
202	      .select('id, name, logo_url, slug, aparencia, frete_motoboy, pagamento_manual, payment_config')
203	      .not('slug', 'is', null)
204	      .eq('bloqueado', false)
205	      .eq('modulo_delivery', true);
206	
207	    if (!restaurantes?.length) return { produtos: [] };
208	
209	    const restIds = restaurantes.map((r) => r.id);
210	    const restMap = Object.fromEntries(restaurantes.map((r) => [r.id, this.exporPagamentoPublico(r)]));
211	
212	    // Busca diretamente por restaurant_id (não depende de category chain)
213	    const { data: produtos, error } = await this.supabase.client
214	      .from('products')
215	      .select(PRODUTO_FIELDS)
216	      .eq('is_active', true)
217	      .gt('quantidade_estoque', 0)
218	      .in('restaurant_id', restIds)
219	      .order('name')
220	      .limit(200);
221	
222	    if (error) throw error;
223	
224	    const resultado = {
225	      produtos: (produtos ?? []).map((p) => ({
226	        ...p,
227	        restaurante: restMap[p.restaurant_id] ?? null,
228	      })).filter((p) => p.restaurante),
229	    };
230	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
231	    return resultado;
232	  }
233	
234	  // Marketplace (home sem domínio customizado): combo ativo de todos os
235	  // estabelecimentos, com estoque de todo ingrediente — mesmo critério
236	  // de disponibilidade do CombosService, só que sem restringir a 1 restaurante.
237	  @Get('combos')
238	  async todosOsCombos() {
239	    const cacheKey = 'catalogo:combos:marketplace';
240	    const cached = await this.redis.getJSON<{ combos: any[] }>(cacheKey);
241	    if (cached) return cached;
242	
243	    const { data: restaurantes } = await this.supabase.client
244	      .from('restaurants')
245	      .select('id, name, logo_url, slug, aparencia, frete_motoboy, pagamento_manual, payment_config')
246	      .not('slug', 'is', null)
247	      .eq('bloqueado', false)
248	      .eq('modulo_delivery', true);
249	
250	    if (!restaurantes?.length) return { combos: [] };
251	
252	    const restIds = restaurantes.map((r) => r.id);
253	    const restMap = Object.fromEntries(restaurantes.map((r) => [r.id, this.exporPagamentoPublico(r)]));
254	
255	    const { data: combos, error } = await this.supabase.client
256	      .from('combos')
257	      .select(
258	        'id, name, description, price, preco_promo, image_url, destaque, restaurant_id, is_active, combo_items(quantity, products(quantidade_estoque, is_active))',
259	      )
260	      .eq('is_active', true)
261	      .in('restaurant_id', restIds)
262	      .order('destaque', { ascending: false })
263	      .order('name')
264	      .limit(200);
265	
266	    if (error) throw error;
267	
268	    const resultado = {
269	      combos: (combos ?? [])
270	        .map((c: any) => {
271	          const { combo_items, ...resto } = c;
272	          const itens = combo_items ?? [];
273	          const disponivel =
274	            itens.length > 0 &&
275	            itens.every((ci: any) => ci.products?.is_active && (ci.products?.quantidade_estoque ?? 0) > 0);
276	          return { ...resto, disponivel, restaurante: restMap[c.restaurant_id] ?? null };
277	        })
278	        .filter((c: any) => c.disponivel && c.restaurante),
279	    };
280	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
281	    return resultado;
282	  }
283	
284	  // Resolução de domínio customizado — precisa vir ANTES de @Get(':slug') na
285	  // ordem das rotas (mesma regra de 'filtros'/'produtos' acima).
286	  @Get('by-domain/:host')
287	  async cardapioPorDominio(@Param('host') host: string) {
288	    const dominio = normalizarDominio(host);
289	    const cacheKey = `catalogo:cardapio:dominio:${dominio}`;
290	    const cached = await this.redis.getJSON<any>(cacheKey);
291	    if (cached) return cached;
292	
293	    const { data: restaurante } = await this.supabase.client
294	      .from('restaurants')
295	      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy, modulo_delivery, pagamento_manual, payment_config')
296	      .eq('custom_domain', dominio)
297	      .maybeSingle();
298	
299	    if (!restaurante) throw new NotFoundException('Domínio não configurado');
300	    const resultado = await this.montarCardapio(restaurante);
301	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
302	    return resultado;
303	  }
304	
305	  @Get(':slug')
306	  async cardapio(@Param('slug') slug: string) {
307	    const cacheKey = `catalogo:cardapio:${slug}`;
308	    const cached = await this.redis.getJSON<any>(cacheKey);
309	    if (cached) return cached;
310	
311	    const { data: restaurante } = await this.supabase.client
312	      .from('restaurants')
313	      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy, modulo_delivery, pagamento_manual, payment_config')
314	      .eq('slug', slug)
315	      .maybeSingle();
316	
317	    if (!restaurante) throw new NotFoundException('Restaurante não encontrado');
318	    const resultado = await this.montarCardapio(restaurante);
319	    await this.redis.setJSON(cacheKey, resultado, TTL_CARDAPIO);
320	    return resultado;
321	  }
322	
323	  // payment_config nunca sai em claro (token PagBank etc) — só a chave PIX é pública,
324	  // e só quando o restaurante está em modo manual (checkout gera o QR local com ela).
325	  private exporPagamentoPublico(r: any) {
326	    const chave_pix = r.pagamento_manual ? (r.payment_config?.chave_pix ?? null) : null;
327	    const { payment_config, ...resto } = r;
328	    return { ...resto, chave_pix };
329	  }
330	
331	  private async montarCardapio(restauranteRaw: any) {
332	    const restaurante = this.exporPagamentoPublico(restauranteRaw);
333	
334	    // Categorias do restaurante (próprias + globais para exibição)
335	    const { data: categorias } = await this.supabase.client
336	      .from('categories')
337	      .select('id, name')
338	      .or(`restaurant_id.eq.${restaurante.id},restaurant_id.is.null`)
339	      .order('name');
340	
341	    // Produtos via restaurant_id (forma correta e direta)
342	    const { data: produtos } = await this.supabase.client
343	      .from('products')
344	      .select(PRODUTO_FIELDS)
345	      .eq('is_active', true)
346	      .gt('quantidade_estoque', 0)
347	      .eq('restaurant_id', restaurante.id)
348	      .order('destaque', { ascending: false })
349	      .order('name');
350	
351	    const cardapio = (categorias ?? []).map((cat) => ({
352	      ...cat,
353	      produtos: (produtos ?? []).filter((p) => p.category_id === cat.id),
354	    })).filter((cat) => cat.produtos.length > 0);
355	
356	    const destaques = (produtos ?? []).filter((p) => p.destaque);
357	    const promos = (produtos ?? []).filter(
358	      (p) => Array.isArray(p.tags) && p.tags.includes('promo') && p.preco_promo != null,
359	    );
360	
361	    // Combos são entidade separada de products — mesmos campos de exibição
362	    // (name/price/preco_promo/image_url/destaque) pra reusar o mesmo card do cliente.
363	    // Some do cardápio se faltar estoque de qualquer produto que o compõe.
364	    const combosDisponiveis = await this.combosService.listarComDisponibilidade(restaurante.id);
365	    const combos = combosDisponiveis.filter((c) => c.disponivel).map((c) => ({ ...c, tipo: 'combo' }));
366	
367	    return { restaurante, cardapio, destaques, promos, combos };
368	  }
369	}
