458	const SingleCartCheckout = () => {
459	  const navigate = useNavigate();
460	  const location = useLocation();
461	
462	  const [restored] = useState(() => {
463	    if (location.state?.carrinho) return location.state;
464	    try {
465	      const s = sessionStorage.getItem('pending_cart');
466	      if (s) { sessionStorage.removeItem('pending_cart'); return JSON.parse(s); }
467	    } catch {}
468	    return {};
469	  });
470	
471	  const { carrinho = [], restauranteId, restauranteSlug, freteMotoboy = 0, pagamentoManual = false, chavePix = null, restauranteNome = null } = restored;
472	
473	  const [itens, setItens] = useState(carrinho);
474	  const [perfil, setPerfil] = useState(null);
475	  const [paymentMethod, setPaymentMethod] = useState('pix');
476	  const [cpf, setCpf] = useState('');
477	  const [trocoPara, setTrocoPara] = useState('');
478	  const [loading, setLoading] = useState(false);
479	  const [erro, setErro] = useState(null);
