481	  const [pixManual, setPixManual] = useState(false);
482	  const [orderId, setOrderId] = useState(null);
483	  const [etapa, setEtapa] = useState(0); // 0=itens 1=endereço 2=pagamento 3=confirmar
484	
485	  useEffect(() => {
486	    getPerfil().then(setPerfil).catch(() => {});
487	  }, []);
488	
489	  const frete = parseFloat(freteMotoboy) || 0;
490	  const subtotal = itens.reduce((acc, i) => acc + i.price * i.qtd, 0);
491	  const total = subtotal + frete;
492	
493	  const irParaStep = (n) => { setErro(null); setEtapa(n); };
494	
