${itens.map((i) => `<div class="item"><span class="col-qtd">${i.quantity}x</span><span class="col-desc">${esc(i.product_name ?? i.products?.name)}</span><span class="col-valor">${fmt(i.quantity * (i.unit_price ?? 0))}</span></div>`).join('')}
<hr/>
<div class="linha"><span>Subtotal</span><span>${fmt(subtotal)}</span></div>
${desconto > 0 ? `<div class="linha"><span>Desconto</span><span>- ${fmt(desconto)}</span></div>` : ''}
${acrescimo > 0 ? `<div class="linha"><span>Acréscimo</span><span>+ ${fmt(acrescimo)}</span></div>` : ''}
${gorjeta > 0 ? `<div class="linha"><span>Gorjeta</span><span>${fmt(gorjeta)}</span></div>` : ''}
${taxaCartao > 0 ? `<div class="linha"><span>Taxa cartão</span><span>+ ${fmt(taxaCartao)}</span></div>` : ''}
<hr/>
<div class="total"><span>TOTAL</span><span>${fmt(total)}</span></div>
${pagamentos.length > 0 ? `
<hr/>
<div class="center" style="font-size:11px;font-weight:bold">PAGAMENTOS</div>
${pagamentos.map((p) => `<div class="linha"><span>${esc(PAYMENT_LABELS[p.forma_pagamento] ?? p.forma_pagamento)} (${esc(PAGAMENTO_ORIGEM[p.origem] ?? p.origem)})${p.taxa_cartao_valor > 0 ? ` + taxa ${fmt(p.taxa_cartao_valor)}` : ''}</span><span>${fmt(p.valor + (p.taxa_cartao_valor || 0))}</span></div>${p.forma_pagamento === 'cash' && p.valor_recebido != null ? `<div class="linha" style="font-size:11px;color:#444"><span>Dinheiro: ${fmt(p.valor_recebido)} · Troco: ${fmt(p.troco || 0)}</span><span></span></div>` : ''}`).join('')}
` : `
<div class="linha"><span>Forma de pagamento</span><span>${esc(PAYMENT_LABELS[formaPagamento] ?? formaPagamento)}</span></div>
`}
${trocoDado > 0 ? `<div class="linha"><span>Troco</span><span>${fmt(trocoDado)}</span></div>` : ''}
<hr/>
<div class="foot">Obrigado pela preferência!</div>
<script>
window.print();
try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
</script>
</body></html>`;

  const frameId = `recibo-frame-${Date.now()}`;
  const iframe = document.createElement('iframe');
  iframe.id = frameId;
  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
  document.body.appendChild(iframe);

  try {
    iframe.contentDocument.open();
    iframe.contentDocument.write(html);
    iframe.contentDocument.close();
  } catch {
    iframe.remove();
    const w = window.open('', '_blank', 'width=440,height=680');
    if (w) { w.document.write(html); w.document.close(); }
  }
};

// Conferência pedida pelo caixa antes de fechar a conta — itens + subtotal e também
// a prévia de acréscimo/gorjeta/taxa/forma de pagamento já escolhidos na tela (ainda
// não é o recibo final, que só sai depois de pago via printReciboCliente).
export const printConferenciaComanda = (comanda, itens, valores = {}, restauranteNome) => {
  const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
  const subtotal = itens.reduce((acc, i) => acc + i.quantity * (i.unit_price ?? i.products?.price ?? 0), 0);
  const { desconto = 0, acrescimo = 0, gorjeta = 0, taxaCartao = 0, formaPagamento, pagamentos = [] } = valores;
  const total = subtotal - desconto + acrescimo + gorjeta + taxaCartao;
  const mesa = comanda?.mesa_id ? `Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}` : 'Comanda avulsa';
  const hora = new Date().toLocaleString('pt-BR');
  const PAGAMENTO_ORIGEM = { garcom: 'garçom', estabelecimento: 'caixa' };
  const barcodeSvg = comanda?.numero_comanda
    ? renderBarcodeSvg('barcode-conferencia', barcodeValue(comanda.numero_comanda), `#${comanda.numero_comanda}`, { width: 1.4, height: 40, fontSize: 10, margin: 2 })
    : null;

  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Conferência</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Courier New',monospace;font-size:14px;padding:12px;color:#000;max-width:300px;margin:0 auto}
.center{text-align:center;display:block}
.rest{font-size:16px;font-weight:bold;margin-bottom:2px}
hr{border:none;border-top:1px dashed #000;margin:8px 0}
.topo{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.topo-info{min-width:0}
#barcode-conferencia{display:block;max-width:120px;flex-shrink:0}
.item{display:flex;gap:8px;padding:3px 0;font-size:14px;justify-content:space-between}
.total{display:flex;justify-content:space-between;font-size:18px;font-weight:900;padding:4px 0}
.foot{font-size:11px;text-align:center;margin-top:8px}
@media print{button{display:none!important}}
</style></head><body>
<div class="topo">
  <div class="topo-info">
    <div class="rest">${esc(restauranteNome ?? 'RESTAURANTE')}</div>
    <div style="font-size:11px;letter-spacing:1px">COMANDA — CONFERÊNCIA</div>
    <div style="font-size:13px;font-weight:bold;margin-top:2px">${esc(mesa)}</div>
  </div>
  ${barcodeSvg ?? ''}
</div>
${comanda?.cliente_mesa_nome ? `<div class="center" style="font-size:12px">${esc(comanda.cliente_mesa_nome)}</div>` : ''}
${comanda?.garcons?.nome ? `<div class="center" style="font-size:12px">Garçom: ${esc(comanda.garcons.nome)}</div>` : ''}
<div class="center" style="font-size:11px">${hora}</div>
<hr/>
${itens.map((i) => `<div class="item"><span>${i.quantity}x ${esc(i.product_name ?? i.products?.name)}</span><span>${fmt(i.quantity * (i.unit_price ?? i.products?.price ?? 0))}</span></div>`).join('')}
<hr/>
<div class="item"><span>Subtotal</span><span>${fmt(subtotal)}</span></div>
${desconto > 0 ? `<div class="item"><span>Desconto</span><span>- ${fmt(desconto)}</span></div>` : ''}
${acrescimo > 0 ? `<div class="item"><span>Acréscimo</span><span>+ ${fmt(acrescimo)}</span></div>` : ''}
${gorjeta > 0 ? `<div class="item"><span>Gorjeta</span><span>+ ${fmt(gorjeta)}</span></div>` : ''}
${taxaCartao > 0 ? `<div class="item"><span>Taxa cartão</span><span>+ ${fmt(taxaCartao)}</span></div>` : ''}
<hr/>
<div class="total"><span>TOTAL</span><span>${fmt(total)}</span></div>
${pagamentos.length > 0 ? `
<hr/>
<div class="center" style="font-size:11px;font-weight:bold">JÁ PAGO</div>
${pagamentos.map((p) => `<div class="item"><span>${esc(PAYMENT_LABELS[p.forma_pagamento] ?? p.forma_pagamento)} (${esc(PAGAMENTO_ORIGEM[p.origem] ?? p.origem)})${p.taxa_cartao_valor > 0 ? ` + taxa ${fmt(p.taxa_cartao_valor)}` : ''}</span><span>${fmt(p.valor + (p.taxa_cartao_valor || 0))}</span></div>`).join('')}
` : formaPagamento ? `<div class="item"><span>Forma de pagamento</span><span>${esc(PAYMENT_LABELS[formaPagamento] ?? formaPagamento)}</span></div>` : ''}
<hr/>
<div class="foot">Confira os itens antes de fechar a conta</div>
<script>
window.print();
try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
</script>
</body></html>`;

  const frameId = `conferencia-frame-${Date.now()}`;
  const iframe = document.createElement('iframe');
  iframe.id = frameId;
  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
  document.body.appendChild(iframe);

  try {
    iframe.contentDocument.open();
    iframe.contentDocument.write(html);
    iframe.contentDocument.close();
  } catch {
    iframe.remove();
    const w = window.open('', '_blank', 'width=440,height=680');
    if (w) { w.document.write(html); w.document.close(); }
  }
};

// Ticket de setor do módulo Salão (cozinha/bar/salgados...) — só os itens novos
// enviados agora, nunca reimprime os que já foram (ver order_items.status no backend).
export const printTicketSetor = (itens, comanda, setorNome) => {
  if (!itens?.length) return;

  const mesa = comanda?.mesaLabel ?? (comanda?.mesa_id ? `Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}` : null);
  const hora = new Date().toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
  // Só comanda do salão tem numero_comanda — item de delivery roteado pra mesma
  // impressora de setor não passa por aqui com esse código, então não ganha barcode.
  const barcodeSvg = comanda?.numero_comanda
    ? renderBarcodeSvg('barcode-setor', barcodeValue(comanda.numero_comanda), `#${comanda.numero_comanda}`, { width: 1.4, height: 40, fontSize: 10, margin: 2 })
    : null;

  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${esc(setorNome)}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Courier New',monospace;font-size:20px;padding:12px;color:#000;max-width:340px;margin:0 auto}
.center{text-align:center;display:block}
hr{border:none;border-top:2px dashed #000;margin:10px 0}
.topo{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:6px}
.topo-info{min-width:0}
.titulo-setor{font-size:28px;font-weight:900;letter-spacing:1px;text-transform:uppercase;margin:0}
.mesa-comanda{font-size:19px;font-weight:800;margin-top:2px}
#barcode-setor{display:block;max-width:130px;flex-shrink:0}
.item-nome{font-size:22px;font-weight:900;margin-top:4px}
.item-qtd{font-size:22px;font-weight:900}
.item-desc,.item-obs{font-size:18px;font-weight:400;padding-left:4px;margin-top:2px}
.separador{border:none;border-top:1px dashed #000;margin:14px 0}
@media print{button{display:none!important}}
</style></head><body>
<div class="topo">
  <div class="topo-info">
    <div class="titulo-setor">${esc(setorNome ?? 'Setor')}</div>
    ${mesa ? `<div class="mesa-comanda">${esc(mesa)}</div>` : ''}
  </div>
  ${barcodeSvg ?? ''}
</div>
${comanda?.garcons?.nome ? `<div class="center" style="font-size:18px;font-weight:bold">Garçom: ${esc(comanda.garcons.nome)}</div>` : ''}
${comanda?.cliente_mesa_nome ? `<div class="center" style="font-size:18px">Cliente: ${esc(comanda.cliente_mesa_nome)}</div>` : ''}
${comanda?.cliente_mesa_telefone ? `<div class="center" style="font-size:18px">Whatsapp: ${esc(comanda.cliente_mesa_telefone)}</div>` : ''}
<div class="center" style="font-size:14px">${hora}</div>
<hr/>
${itens.map((i, idx) => `
<div class="item-nome">${esc(i.product_name)}</div>
<div class="item-qtd">Qtd: ${i.quantity}</div>
${i.description ? `<div class="item-desc">Descrição: ${esc(i.description)}</div>` : ''}
${i.observacao ? `<div class="item-obs">Obs: ${esc(i.observacao)}</div>` : ''}
${idx < itens.length - 1 ? '<hr class="separador"/>' : ''}
`).join('')}
<hr/>
<script>
window.print();
try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
</script>
</body></html>`;

  const frameId = `setor-frame-${Date.now()}`;
  const iframe = document.createElement('iframe');
  iframe.id = frameId;
  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
  document.body.appendChild(iframe);

  try {
    iframe.contentDocument.open();
    iframe.contentDocument.write(html);
    iframe.contentDocument.close();
  } catch {
    iframe.remove();
    const w = window.open('', '_blank', 'width=440,height=680');
    if (w) { w.document.write(html); w.document.close(); }
  }
};

